/* food search sheet */
var SH={meal:null,q:"",pick:null,g:null,remote:[],busy:false};
function sheetEl(){var s=$id("lg2sheet");if(!s){s=document.createElement("div");s.id="lg2sheet";s.innerHTML='<div class="in" id="lg2sheetIn"></div>';document.body.appendChild(s);s.addEventListener("click",function(e){if(e.target===s)closeSheet();});}return s;}
function closeSheet(){var s=$id("lg2sheet");if(s)s.classList.remove("on");document.body.style.overflow="";}
window.lg2OpenSearch=function(meal){SH={meal:meal,q:"",pick:null,g:null,remote:[],busy:false};sheetEl();drawSheet();$id("lg2sheet").classList.add("on");document.body.style.overflow="hidden";setTimeout(function(){var i=$id("fq");if(i)i.focus();},250);};
function localHits(q){if(!q)return RECENT.map(function(n){return FOODS.filter(function(f){return f.n===n;})[0];}).filter(Boolean).concat(FOODS.filter(function(f){return RECENT.indexOf(f.n)<0;}).slice(0,12)).slice(0,14);var w=q.toLowerCase().split(/\s+/);return FOODS.filter(function(f){var t=(f.n+" "+f.cat).toLowerCase();return w.every(function(x){return t.indexOf(x)>=0;});}).slice(0,20);}
var offT=null;function offSearch(q){clearTimeout(offT);if(q.length<3){SH.remote=[];return;}offT=setTimeout(function(){SH.busy=true;drawList();fetch("https://world.openfoodfacts.org/cgi/search.pl?search_terms="+encodeURIComponent(q)+"&search_simple=1&action=process&json=1&page_size=8&fields=product_name,brands,nutriments,serving_quantity").then(function(r){return r.json();}).then(function(j){SH.remote=(j.products||[]).filter(function(p){return p.product_name&&p.nutriments&&p.nutriments["energy-kcal_100g"]!=null;}).map(function(p){var n=p.nutriments;return {n:p.product_name+(p.brands?" · "+p.brands.split(",")[0]:""),cat:"Packaged",k:Math.round(n["energy-kcal_100g"]),p:+(n.proteins_100g||0),c:+(n.carbohydrates_100g||0),f:+(n.fat_100g||0),s:+(p.serving_quantity)||100,sl:"serve",src:"off"};});SH.busy=false;drawList();}).catch(function(){SH.busy=false;SH.remote=[];drawList();});},450);}
function drawSheet(){$id("lg2sheetIn").innerHTML='<h3>Add to '+E(SH.meal)+'</h3><div class="search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg><input id="fq" placeholder="Search: chicken, oats, Up&Go, Tim Tam…" autocomplete="off"></div><div id="fl"></div>';$id("fq").addEventListener("input",function(){SH.q=$id("fq").value.trim();SH.pick=null;drawList();offSearch(SH.q);});drawList();}
function drawList(){var el=$id("fl");if(!el)return;
  if(SH.pick){var f=SH.pick,g=SH.g,en=entry(f,g);el.innerHTML='<div class="card2" style="margin-top:12px"><b style="font-size:15px">'+E(f.n)+'</b><div class="muted" style="font-size:11.5px;margin-top:3px">'+f.k+' kcal per 100 g · 1 '+E(f.sl)+' = '+f.s+' g</div><div class="qty"><div class="field"><label>Grams</label><input id="fg" type="number" inputmode="decimal" value="'+g+'"></div><div class="field"><label>Serves</label><input id="fs" type="number" inputmode="decimal" step="0.5" value="'+(g/f.s).toFixed(2).replace(/\.?0+$/,"")+'"></div></div><div class="sumline"><div><b>'+en.k+'</b><i>kcal</i></div><div><b>'+Math.round(en.p)+'</b><i>protein</i></div><div><b>'+Math.round(en.c)+'</b><i>carbs</i></div><div><b>'+Math.round(en.f)+'</b><i>fat</i></div></div><div style="display:flex;gap:8px;margin-top:12px"><button class="btn" style="flex:1" id="fadd">Add to '+E(SH.meal)+'</button><button class="btn ghost" id="fback">Back</button></div></div>';
    $id("fg").addEventListener("input",function(){SH.g=+$id("fg").value||0;$id("fs").value=(SH.g/f.s).toFixed(2).replace(/\.?0+$/,"");upd();});$id("fs").addEventListener("input",function(){SH.g=Math.round((+$id("fs").value||0)*f.s);$id("fg").value=SH.g;upd();});
    function upd(){var e2=entry(f,SH.g);var b=el.querySelectorAll(".sumline b");b[0].textContent=e2.k;b[1].textContent=Math.round(e2.p);b[2].textContent=Math.round(e2.c);b[3].textContent=Math.round(e2.f);}
    $id("fadd").addEventListener("click",function(){if(!SH.g)return;dayLog(FDAY())[SH.meal].push(entry(f,SH.g));RECENT=[f.n].concat(RECENT.filter(function(x){return x!==f.n;})).slice(0,10);fuelSave();closeSheet();buzz(8);T("Added "+f.n.split(",")[0]);renderFuel();});
    $id("fback").addEventListener("click",function(){SH.pick=null;drawList();});return;}
  var loc=localHits(SH.q),rows=loc.map(function(f,i){return '<button class="fr" data-fi="l'+i+'"><div><b>'+E(f.n)+'</b><small>'+E(f.cat)+' · 1 '+E(f.sl)+' ('+f.s+' g) · P '+f.p+' C '+f.c+' F '+f.f+' per 100 g</small></div><span class="kc">'+Math.round(f.k*f.s/100)+'</span></button>';}).join("");
  var rem=SH.remote.map(function(f,i){return '<button class="fr" data-fi="r'+i+'"><div><b>'+E(f.n)+'</b><small>Packaged · '+f.k+' kcal per 100 g · P '+f.p+' C '+f.c+' F '+f.f+'</small></div><span class="kc">'+f.k+'</span></button>';}).join("");
  el.innerHTML='<div class="lg2">'+(SH.q?'':'<h2 class="sec" style="margin-top:14px">'+(RECENT.length?"Recent & common":"Common foods")+'</h2>')+'<div class="card2" style="padding:4px 12px;margin-top:'+(SH.q?"12px":"0")+'">'+(rows||'<div class="muted" style="padding:12px 0;font-size:13px">Nothing in the Legacy list. Packaged products are searched below.</div>')+'</div>'+(SH.q.length>=3?'<h2 class="sec">Packaged products <small>'+(SH.busy?"searching…":SH.remote.length?"Open Food Facts":"none found")+'</small></h2>'+(rem?'<div class="card2" style="padding:4px 12px">'+rem+'</div>':'')+'<div class="srcnote">Built-in foods are Legacy\'s own list. Packaged products come from Open Food Facts, the open barcode database.</div>':'')+'</div>';
  [].forEach.call(el.querySelectorAll("[data-fi]"),function(b){b.addEventListener("click",function(){var id=b.dataset.fi,f=id.charAt(0)==="l"?loc[+id.slice(1)]:SH.remote[+id.slice(1)];SH.pick=f;SH.g=f.s;drawList();});});}

