window.lg2PostNotice=function(){var el=$id("nBody");if(!el)return;var body=el.value.trim();if(!body){T("Write the notice first");return;}sb.from("gym_announcements").update({active:false}).eq("active",true).then(function(){return sb.from("gym_announcements").insert({body:body,active:true,created_by:me()});}).then(function(r){if(r.error){T(r.error.message);return;}try{ANN=undefined;}catch(e){}T("Posted. It\'s on every home screen.");AD.loading=false;adminLoad();});};
